SELECT id, carrier, shipped_date, delivered_date, cost, STDDEV_SAMP(cost) OVER w_recent AS carrier_stddev_samp_cost, STDDEV_SAMP(cost) OVER (PARTITION BY status, order_id) AS status_stddev_samp_cost, LAST_VALUE(carrier) IGNORE NULLS OVER w_running AS last_known_carrier FROM shipments WINDOW w_recent AS (PARTITION BY carrier), w_running AS (PARTITION BY MONTH(delivered_date), status ORDER BY cost ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
